function makeCounter(start = 0) {
  let count = start;            // private, kept alive by the closures below
  return {
    increment: () => ++count,
    decrement: () => --count,
    value: () => count
  };
}

const a = makeCounter();
const b = makeCounter(10);
a.increment();
a.increment();
b.decrement();
console.log(a.value(), b.value()); // 2 9

