practice.solution:
function makeCounter(start, step) {
  let value = start;
  return {
    inc: () => { value += step; },
    dec: () => { value -= step; },
    reset: () => { value = start; },
    get: () => value
  };
}

const lines = stdin.trim().split('\n');
const n = parseInt(lines[0], 10);
const counters = new Map();
const out = [];
for (let i = 1; i <= n; i++) {
  const [cmd, name, a, b] = lines[i].trim().split(/\s+/);
  if (cmd === 'create') {
    if (counters.has(name)) { out.push('error: ' + name + ' exists'); continue; }
    counters.set(name, makeCounter(Number(a), Number(b)));
    continue;
  }
  const counter = counters.get(name);
  if (!counter) { out.push('error: ' + name + ' not found'); continue; }
  if (cmd === 'get') out.push(name + '=' + counter.get());
  else counter[cmd]();
}
console.log(out.join('\n'));

